    try:
        outcome = candidate(lambda workspace, request: response, 'w', {'label': 'blue'})
        assert outcome == {'saved': True, 'enhanced': False}
        result = 'success'
    except RuntimeError as error:
        result = str(error)
    assert result == expected
    print('receipt control', response, result)
